#include "freent_nt.h"
int freent_command_line_has(const WCHAR *word, USHORT word_length) { UNICODE_STRING line = freent_current_peb()->ProcessParameters->CommandLine; USHORT characters = (USHORT)(line.Length / sizeof(WCHAR)); USHORT needed = (USHORT)(word_length / sizeof(WCHAR)); USHORT i; for (i = 0; i + needed <= characters; ++i) { USHORT j = 0; for (; j < needed && line.Buffer[i + j] == word[j]; ++j) { } if (j == needed) return 1; } return 0; }
static void show_help(void) { freent_write("FreeNT native userland\r\n\r\nUsage: freent.exe <command>\r\n\r\nCommands:\r\n  info       Show NT version information\r\n  version    Show FreeNT version\r\n  help       Show this help\r\n"); }
static void show_info(void) { OSVERSIONINFOW version; version.dwOSVersionInfoSize = sizeof(version); if (!NT_SUCCESS(RtlGetVersion(&version))) { freent_write("Unable to query NT version.\r\n"); return; } freent_write("FreeNT native userland\r\nNT version: "); freent_write_u32(version.dwMajorVersion); freent_write("."); freent_write_u32(version.dwMinorVersion); freent_write(" (build "); freent_write_u32(version.dwBuildNumber); freent_write(")\r\nNative API provider: ntdll.dll\r\n"); }
static void run_login_manager(void) { char username[128]; ULONG username_length; NTSTATUS status; freent_write("FreeNT logind\r\nNative console session manager\r\n\r\nlogin: "); status = freent_read_line(username, sizeof(username), &username_length); if (!NT_SUCCESS(status) || username_length == 0) { freent_zero(username, sizeof(username)); freent_write("Login name was not accepted.\r\n"); return; } freent_write("Requested local session for: "); freent_write(username); freent_write("\r\n\r\nAuthentication is intentionally delegated to an LSA logon broker.\r\nThis native session manager does not collect passwords or create a token.\r\n"); freent_zero(username, sizeof(username)); }
void freent_dispatch(void) { static const WCHAR info[] = { 'i','n','f','o' }; static const WCHAR login[] = { 'l','o','g','i','n' }; static const WCHAR version[] = { 'v','e','r','s','i','o','n' }; if (freent_command_line_has(login, sizeof(login))) run_login_manager(); else if (freent_command_line_has(info, sizeof(info))) show_info(); else if (freent_command_line_has(version, sizeof(version))) freent_write("FreeNT 0.2.0-native\r\n"); else show_help(); }
